/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
from random import Random
from cadence import agenda, occurrences
r = Random(801)
def timestamp(minute):
    return f'2025-01-01T{minute // 60:02}:{minute % 60:02}'
def index(t):
    return int(t[11:13]) * 60 + int(t[14:16])
for case in range(1000):
    rules, intervals = [], []
    lo, hi = sorted(r.sample(range(140), 2))
    minimum = r.randrange(20)
    for i in range(r.randrange(14)):
        start = r.randrange(120)
        end = start + r.randrange(1, 40)
        priority = r.randrange(-2, 3)
        rules.append({'id': str(i), 'priority': priority,
                      'rule': f'every day at {timestamp(start)[11:]} for {end - start}m from 2025-01-01 times 1'})
        if start < hi and end > lo:
            intervals.append((i, start, end, priority))
    p = {'timezone': 'UTC', 'rules': rules}
    if minimum:
        p['min_segment'] = f'{minimum}m'
    args = p, timestamp(lo)+'Z', timestamp(hi)+'Z'
    want_order = [str(i) for i,s,e,k in sorted(intervals, key=lambda row: (row[1],row[2],-row[3],row[0]))]
    assert [row['rule'] for row in occurrences(*args)] == want_order
    claimed, expected = set(), {}
    for i, s, e, k in sorted(intervals, key=lambda row: (-row[3],row[1],row[0])):
        whole = set(range(s,e))
        available = whole - claimed
        claimed |= whole
        segment = []
        for t in range(s,e+1):
            if t in available:
                segment.append(t)
            elif segment:
                if available == whole or len(segment) >= minimum:
                    expected.update((m,str(i)) for m in segment if lo <= m < hi)
                segment = []
    actual = {}
    for row in agenda(*args):
        for minute in range(index(row['start']),index(row['end'])):
            assert minute not in actual
            actual[minute] = row['rule']
    assert actual == expected, case
print('1,000 generated overlap cases matched the reference')
PY"

